RENAME TABLE memberships TO institution_memberships;
ALTER TABLE institution_memberships MODIFY role ENUM('admin','teacher','student','employee','parent','ops') NOT NULL, ADD active TINYINT NOT NULL DEFAULT 1;
CREATE ALGORITHM=MERGE VIEW memberships AS SELECT org_id,user_id,role,class_name,reference_number,created_at,display_name FROM institution_memberships WHERE active=1 AND role<>'ops' WITH CASCADED CHECK OPTION;
CREATE TABLE emis_campuses (org_id CHAR(36) PRIMARY KEY, profile JSON NOT NULL, FOREIGN KEY(org_id) REFERENCES organizations(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE emis_records (org_id CHAR(36) NOT NULL,id VARCHAR(64) NOT NULL,entity VARCHAR(64) NOT NULL,year VARCHAR(7) NOT NULL,data JSON NOT NULL,version INT NOT NULL DEFAULT 1,sample TINYINT NOT NULL DEFAULT 0,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,archived TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(org_id,id),INDEX(org_id,entity,year,archived),FOREIGN KEY(org_id) REFERENCES emis_campuses(org_id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE emis_student_links (org_id CHAR(36) NOT NULL,student_id VARCHAR(64) NOT NULL,person_id VARCHAR(64) NOT NULL,previous_id VARCHAR(64),PRIMARY KEY(org_id,student_id),UNIQUE(org_id,previous_id),INDEX(org_id,person_id),FOREIGN KEY(org_id,student_id) REFERENCES emis_records(org_id,id),FOREIGN KEY(org_id,previous_id) REFERENCES emis_records(org_id,id)) ENGINE=InnoDB;
CREATE TABLE emis_roles (org_id CHAR(36) NOT NULL,user_id CHAR(36) NOT NULL,role VARCHAR(64) NOT NULL,student_id VARCHAR(64),student_person_id VARCHAR(64),faculty_id VARCHAR(64),program_id VARCHAR(64),PRIMARY KEY(org_id,user_id),UNIQUE(org_id,student_id),UNIQUE(org_id,student_person_id),UNIQUE(org_id,faculty_id),FOREIGN KEY(org_id) REFERENCES emis_campuses(org_id),FOREIGN KEY(org_id,user_id) REFERENCES institution_memberships(org_id,user_id) ON DELETE CASCADE,FOREIGN KEY(org_id,student_id) REFERENCES emis_records(org_id,id),FOREIGN KEY(org_id,faculty_id) REFERENCES emis_records(org_id,id),FOREIGN KEY(org_id,program_id) REFERENCES emis_records(org_id,id)) ENGINE=InnoDB;
CREATE TABLE emis_files (org_id CHAR(36) NOT NULL,id VARCHAR(64) NOT NULL,record_id VARCHAR(64) NOT NULL,name VARCHAR(180) NOT NULL,mime VARCHAR(100) NOT NULL,size INT NOT NULL,path VARCHAR(64) NOT NULL,created_at VARCHAR(30) NOT NULL,PRIMARY KEY(org_id,id),FOREIGN KEY(org_id,record_id) REFERENCES emis_records(org_id,id)) ENGINE=InnoDB;
CREATE TABLE emis_audit (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,org_id CHAR(36) NOT NULL,actor VARCHAR(200) NOT NULL,actor_id VARCHAR(64),action VARCHAR(200) NOT NULL,entity VARCHAR(64),record_id VARCHAR(64),before_data JSON,after_data JSON,created_at VARCHAR(30) NOT NULL,INDEX(org_id,id),INDEX(org_id,record_id),FOREIGN KEY(org_id) REFERENCES emis_campuses(org_id)) ENGINE=InnoDB;
CREATE TABLE emis_rollovers (org_id CHAR(36) NOT NULL,id VARCHAR(64) NOT NULL,user_id VARCHAR(64) NOT NULL,request_id VARCHAR(64) NOT NULL,request_digest CHAR(64) NOT NULL,data JSON NOT NULL,created_at VARCHAR(30) NOT NULL,PRIMARY KEY(org_id,id),UNIQUE(org_id,request_id),FOREIGN KEY(org_id) REFERENCES emis_campuses(org_id)) ENGINE=InnoDB;
CREATE TABLE emis_subject_links (org_id CHAR(36) NOT NULL,record_id VARCHAR(64) NOT NULL,subject_id CHAR(36) NOT NULL,PRIMARY KEY(org_id,record_id),FOREIGN KEY(org_id,record_id) REFERENCES emis_records(org_id,id),FOREIGN KEY(subject_id) REFERENCES subjects(id)) ENGINE=InnoDB;
